parameters.jsCode:
// Verify the Business Agent Platform signature, then emit one flat row per event.
// Requires the environment variables BAP_WEBHOOK_SECRET (the secret from the admin API) and
// NODE_FUNCTION_ALLOW_BUILTIN=crypto (so this Code node may use Node's crypto module).
const crypto = require('crypto');
const secret = $env.BAP_WEBHOOK_SECRET;
if (!secret) throw new Error('BAP_WEBHOOK_SECRET is not set');

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = Number(headers['x-bap-timestamp']);
const signature = String(headers['x-bap-signature'] || '');
const raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');

// Reject replays: the signed timestamp must be within five minutes.
if (!Number.isFinite(timestamp) || Math.abs(Date.now() / 1000 - timestamp) > 300) {
  throw new Error('Stale or missing X-BAP-Timestamp');
}
const expected = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
const valid = expected.length === signature.length &&
  crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
if (!valid) throw new Error('Invalid X-BAP-Signature');

const event = JSON.parse(raw);
const data = event.data || {};
return [{
  json: {
    received_at: new Date().toISOString(),
    event_id: event.id,
    event_type: event.type,
    created_at: event.created_at,
    name: data.name || '',
    phone_or_contact: data.phone || data.contact || '',
    when: data.starts_at || '',
    party_size: data.party_size || '',
    reference: data.reference || '',
    interest: data.interest || '',
    notes: data.notes || '',
  },
}];

